// Entradas: corpo do Webhook ({ "clientes": [...] }) e o CSV de investimentos (texto).
const corpo = $('Webhook').first().json.body ?? {};
const clientes = Array.isArray(corpo.clientes) ? corpo.clientes : [];
const csv = String($('Ler investimentos (CSV)').first().json.data ?? '');

const AVISO = 'Dados fictícios, para fins educacionais. Não é recomendação de investimento.';
// O Webhook é aberto: limita o lote para que um envio grande não esgote a cota do Gemini
const MAX_CLIENTES = 50;
if (clientes.length > MAX_CLIENTES) {
  return [{ json: {
    total: 0,
    aviso: AVISO,
    erro: `Limite de ${MAX_CLIENTES} clientes por envio (recebidos: ${clientes.length}). Divida a lista em lotes menores.`,
    mensagens: [],
  } }];
}

const normalizar = (s) =>
  String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim().toLowerCase();

// "R$ 12.500,00" -> 12500
const lerValor = (s) => {
  const limpo = String(s ?? '').replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.');
  const n = parseFloat(limpo);
  return Number.isFinite(n) ? n : null;
};

// 12500 -> "R$ 12.500,00" (sem toLocaleString: evita o espaço não separável)
const reais = (n) => {
  const [inteiro, centavos] = n.toFixed(2).split('.');
  return `R$ ${inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, '.')},${centavos}`;
};

// "6.2%" -> "6,2%"; "IPCA+6.0%" -> "IPCA + 6,0%"; "Variável" -> "rentabilidade variável"
const rentabilidade = (r) =>
  normalizar(r).startsWith('variavel')
    ? 'rentabilidade variável'
    : r.replace(/\+/g, ' + ').replace(/(\d)\.(\d)/g, '$1,$2');

const listar = (itens) =>
  itens.length <= 1 ? itens.join('') : `${itens.slice(0, -1).join(', ')} e ${itens[itens.length - 1]}`;

// CSV simples (sem aspas): perfil,produto,minimo,rentabilidade
const [cabecalho, ...linhas] = csv.trim().split(/\r?\n/);
const colunas = cabecalho.split(',').map((c) => normalizar(c));
const produtos = linhas
  .filter((l) => l.trim())
  .map((l) => {
    const v = l.split(',');
    const p = Object.fromEntries(colunas.map((c, i) => [c, (v[i] ?? '').trim()]));
    return { perfil: p.perfil, produto: p.produto, minimo: Number(p.minimo), rentabilidade: p.rentabilidade };
  });

const ABERTURA = {
  conservador: 'Como seu perfil é Conservador, priorizamos renda fixa, com foco em segurança e liquidez.',
  moderado: 'Como seu perfil é Moderado, sugerimos equilibrar proteção e crescimento, combinando prefixado, inflação e multimercado.',
  arrojado: 'Como seu perfil é Arrojado, destacamos renda variável, com maior potencial de retorno e também mais oscilação.',
};

const mensagens = clientes.map((c) => {
  const nome = String(c.nome ?? '').trim();
  const primeiroNome = nome.split(/\s+/)[0] || 'cliente';
  const chavePerfil = normalizar(c.perfil);
  const saldo = lerValor(c.saldo);
  const base = { nome, email: String(c.email ?? '').trim(), perfil: String(c.perfil ?? '').trim(), saldo };

  if (!ABERTURA[chavePerfil]) {
    return { ...base, status: 'perfil_invalido', recomendados: [], fora_do_alcance: [],
      mensagem: `Olá, ${primeiroNome}! Não encontramos um perfil de investidor válido no seu cadastro. Atualize seu questionário de perfil para receber recomendações.` };
  }
  if (saldo === null) {
    return { ...base, status: 'saldo_invalido', recomendados: [], fora_do_alcance: [],
      mensagem: `Olá, ${primeiroNome}! Não conseguimos ler o saldo da sua conta. Fale com a gente para atualizar seus dados.` };
  }

  const doPerfil = produtos.filter((p) => normalizar(p.perfil) === chavePerfil);
  const cabem = doPerfil.filter((p) => p.minimo <= saldo);
  const naoCabem = doPerfil.filter((p) => p.minimo > saldo);

  let texto = `Olá, ${primeiroNome}! ${ABERTURA[chavePerfil]}`;
  if (cabem.length) {
    const itens = cabem.map((p) => `${p.produto} (${rentabilidade(p.rentabilidade)}, a partir de ${reais(p.minimo)})`);
    texto += ` Com o seu saldo de ${reais(saldo)}, você já pode aplicar em: ${listar(itens)}.`;
  } else {
    texto += ` Com o seu saldo de ${reais(saldo)}, ainda não há opção disponível para o seu perfil.`;
  }
  for (const p of naoCabem) {
    texto += ` Faltam ${reais(p.minimo - saldo)} para ${p.produto} (mínimo de ${reais(p.minimo)}).`;
  }
  texto += ' Conte com a gente para montar sua carteira!';

  return {
    ...base,
    status: cabem.length ? 'ok' : 'sem_produto_no_saldo',
    recomendados: cabem.map((p) => p.produto),
    fora_do_alcance: naoCabem.map((p) => p.produto),
    mensagem: texto,
  };
});

return [{ json: {
  total: mensagens.length,
  aviso: AVISO,
  mensagens,
} }];

options.systemMessage:
Você é o assistente de relacionamento de uma corretora brasileira. Escreva UMA mensagem curta (até 80 palavras), em português do Brasil, cordial e direta, para o cliente indicado.
Reescreva com as suas palavras: não copie frases dos FATOS. Personalize pelo momento do cliente (quem está começando, quem já tem um bom saldo, quem está perto de alcançar um novo produto).
Regras obrigatórias:
- use somente os produtos, valores e rentabilidades que aparecem nos FATOS, escritos exatamente como lá; não cite nenhum outro produto, taxa ou número;
- se os FATOS disserem quanto falta para um produto, mencione isso como próximo passo;
- não prometa retorno e não use as expressões "garantido" ou "sem risco";
- trate o cliente pelo primeiro nome e termine convidando-o a conversar com a equipe;
- responda apenas com o texto da mensagem, sem título, sem aspas e sem markdown.

