// Junta a saída do agente com os dados de cada cliente. O texto da IA só é usado
// se passar na conferência; senão, vale a mensagem fixa (gerada pelas regras).
const clientes = $('Separar clientes').all().map((i) => i.json);
const respostas = $input.all().map((i) => i.json);
const base = $('Cruzar perfis e gerar mensagens').first().json;
const csv = String($('Ler investimentos (CSV)').first().json.data ?? '');

const normalizar = (s) =>
  String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

const todosProdutos = csv.trim().split(/\r?\n/).slice(1)
  .map((l) => l.split(',')[1]?.trim())
  .filter(Boolean);

const PROMESSA = /garantid|sem risco|risco zero|retorno cert|lucro cert/;

const conferir = (cliente, r, texto) => {
  if (!['ok', 'sem_produto_no_saldo'].includes(cliente.status)) return 'cadastro incompleto: não usa IA';
  if (r.error) return 'falha na chamada à IA';
  if (texto.length < 40) return 'IA sem resposta';
  if (texto.length > 1500) return 'texto longo demais';
  const t = normalizar(texto);
  const permitidos = [...cliente.recomendados, ...cliente.fora_do_alcance].map(normalizar);
  const intruso = todosProdutos.find((p) => !permitidos.includes(normalizar(p)) && t.includes(normalizar(p)));
  if (intruso) return `citou produto fora da lista (${intruso})`;
  if (PROMESSA.test(t)) return 'prometeu retorno ou ausência de risco';
  // Todo valor em R$ e todo percentual do texto tem de existir nos fatos (a mensagem fixa)
  const numeros = texto.match(/R\$\s?\d[\d.,]*|\d[\d.,]*\s?%/g) ?? [];
  const inventado = numeros
    .map((n) => n.replace(/R\$\s?|\s?%/g, '').replace(/[.,]$/, ''))
    .find((n) => !cliente.mensagem.includes(n));
  if (inventado) return `número que não está nos fatos (${inventado})`;
  return null;
};

const mensagens = clientes.map((cliente, i) => {
  const r = respostas[i] ?? {};
  const texto = typeof r.output === 'string' ? r.output.trim() : '';
  const motivo = conferir(cliente, r, texto);
  return motivo
    ? { ...cliente, origem: 'modelo_fixo', motivo }
    : { ...cliente, mensagem: texto, mensagem_fixa: cliente.mensagem, origem: 'ia' };
});

return [{ json: {
  total: mensagens.length,
  geradas_por_ia: mensagens.filter((m) => m.origem === 'ia').length,
  aviso: base.aviso,
  mensagens,
} }];
